using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using ParkingLotEnvironment.Training;
namespace ParkingLotEnvironment.CloudPilot {
public static class VehicleAppearance {
 static readonly Dictionary<Material,Material> materials=new Dictionary<Material,Material>();static readonly Dictionary<Mesh,Mesh> meshes=new Dictionary<Mesh,Mesh>();static int meshCount;
 static string Kind(Material m){string n=m.name.ToLowerInvariant();if(n.Contains("tire")||n.Contains("tyre")||n.Contains("rubber"))return "tire";if(n.Contains("wheel")||n.Contains("alloy")||n.Contains("volk_ra")||n=="disc")return "wheel";if(m.shader.name.Contains("/Glass")||m.shader.name.Contains("AutomotiveGlass"))return "glass";if(n.StartsWith("parked_")&&!n.Contains("commercialblue"))return "paint";if(n.Contains("i30_")||n.Contains("tucson0_")||n.Contains("tucson5_")||n.Contains("azera3_")||n.Contains("azera6_"))return "paint";if(n.Contains("chrome"))return "chrome";if(n.Contains("cladding")||n.Contains("trim"))return "trim";return null;}
 static Mesh Smooth(Mesh source){if(meshes.TryGetValue(source,out var found))return found;if(!source.isReadable)return source;var vv=source.vertices;var nn=source.normals;if(nn.Length!=vv.Length)return source;var buckets=new Dictionary<Vector3Int,List<int>>();for(int i=0;i<vv.Length;i++){var p=vv[i];var key=new Vector3Int(Mathf.RoundToInt(p.x*4000),Mathf.RoundToInt(p.y*4000),Mathf.RoundToInt(p.z*4000));if(!buckets.TryGetValue(key,out var indices))buckets[key]=indices=new List<int>();indices.Add(i);}var result=(Vector3[])nn.Clone();foreach(var bucket in buckets.Values){if(bucket.Count<2)continue;foreach(int i in bucket){Vector3 sum=Vector3.zero;foreach(int j in bucket)if(Vector3.Dot(nn[i].normalized,nn[j].normalized)>.70f)sum+=nn[j].normalized;if(sum.sqrMagnitude>.01f)result[i]=sum.normalized;}}var mesh=UnityEngine.Object.Instantiate(source);mesh.name="VehicleWeldNormals_"+meshCount++;mesh.normals=result;mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,ContextBuilder.W+"/"+mesh.name+".asset");meshes[source]=mesh;return mesh;}
 public static void Apply(GameObject root,string output){var layout=root.GetComponentInChildren<ParkingTrainingLayout>();int count=0;foreach(var obstacle in layout.obstacles){if(obstacle.id.Contains("PortedModel"))continue;var t=layout.transform.Find(obstacle.id);if(!t)throw new Exception("Missing obstacle "+obstacle.id);foreach(var r in t.GetComponentsInChildren<MeshRenderer>()){var slots=r.sharedMaterials;bool smooth=false;for(int k=0;k<slots.Length;k++){var src=slots[k];if(!src)continue;var kind=Kind(src);if(kind==null)continue;if(kind=="glass"||kind=="paint")smooth=true;if(!materials.TryGetValue(src,out var m)){m=new Material(src){name="VehicleFinish_"+materials.Count+"_"+kind};switch(kind){case "paint":m.SetFloat("_Glossiness",.74f);m.SetFloat("_Metallic",.24f);break;case "glass":m.color=new Color(.024f,.035f,.044f,.84f);m.SetFloat("_Glossiness",.92f);break;case "tire":m.color=new Color(.062f,.066f,.071f);m.SetFloat("_Metallic",0);m.SetFloat("_Glossiness",.16f);break;case "wheel":m.color=new Color(.48f,.51f,.54f);m.SetFloat("_Metallic",.72f);m.SetFloat("_Glossiness",.46f);break;case "chrome":m.color=new Color(.62f,.65f,.68f);m.SetFloat("_Metallic",.9f);m.SetFloat("_Glossiness",.74f);break;case "trim":m.SetFloat("_Metallic",0);m.SetFloat("_Glossiness",.21f);break;}AssetDatabase.CreateAsset(m,ContextBuilder.W+"/"+m.name+".mat");materials[src]=m;}slots[k]=m;count++;}r.sharedMaterials=slots;r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;r.receiveShadows=true;var filter=r.GetComponent<MeshFilter>();if(smooth&&filter&&filter.sharedMesh)filter.sharedMesh=Smooth(filter.sharedMesh);}}
  // Restore the delivery truck's accidental blue numberplate recolour from the prior pass.
  var box=layout.transform.Find("Parked_P_BoxTruck");var original=root.transform.Find("DaylightPass_Context/Daylight_ProvisionalTruck");foreach(var r in box.GetComponentsInChildren<Renderer>()){var source=original.GetComponentsInChildren<Renderer>(true).FirstOrDefault(s=>s.name==r.name);if(!source)continue;var mm=r.sharedMaterials;for(int i=0;i<mm.Length;i++)if(mm[i]&&mm[i].name.StartsWith("Parked_P_BoxTruck_CommercialBlue"))mm[i]=source.sharedMaterials[i];r.sharedMaterials=mm;}
  var baseProbe=root.GetComponentsInChildren<ReflectionProbe>(true).First();foreach(int side in new[]{0,1}){var g=new GameObject(side==0?"LeftVehicles_LocalReflection":"RightVehicles_LocalReflection");g.transform.SetParent(root.transform,false);g.transform.position=side==0?new Vector3(-4.2f,1.4f,-9):new Vector3(5.9f,1.4f,-1);var p=g.AddComponent<ReflectionProbe>();p.boxProjection=true;p.size=side==0?new Vector3(16,9,28):new Vector3(12,9,36);p.center=Vector3.zero;p.resolution=512;p.hdr=true;p.mode=ReflectionProbeMode.Baked;p.cullingMask=baseProbe.cullingMask;p.clearFlags=ReflectionProbeClearFlags.Skybox;p.blendDistance=3;p.importance=2;p.enabled=false;}
  File.AppendAllText(output+"/context-changes.txt","Vehicle finish: "+count+" cloned material slots, "+meshes.Count+" welded-normal meshes; two local box reflection captures. Approved Standard/PBR workflow retained; no source assets edited.\n");
 }
}}
